import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"37、【家人】 離下巽上","description":"周易口訣義 - 37、【家人】 離下巽上","frontmatter":{"title":"37、【家人】 離下巽上","description":"周易口訣義 - 37、【家人】 離下巽上"},"headers":[],"relativePath":"classics/koujueyi/039.md","filePath":"classics/koujueyi/039.md"}'),r={name:"classics/koujueyi/039.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_37、【家人】-離下巽上" tabindex="-1">37、【家人】 離下巽上 <a class="header-anchor" href="#_37、【家人】-離下巽上" aria-label="Permalink to “37、【家人】 離下巽上”">​</a></h1><p>彖曰：家人，女正位乎內，男正位乎外。男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父、子子、兄兄、弟弟、夫夫、婦婦，而家道正，正家而天下定矣。象曰：風自火出，家人。君子以言有物而行有恆。</p><p>初九：閒有家，悔亡。</p><p>象曰：「閒有家」，志未變也。</p><p>六二：無攸遂，在中饋，貞吉。</p><p>象曰：六二之吉，順以巽也。</p><p>九三：家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。</p><p>象曰：「家人嗃嗃」，未失也；「婦子嘻嘻」，失家節也。</p><p>六四，富家，大吉。</p><p>象曰：「富家大吉」，順在位也。</p><p>九五，王假有家，勿恤，吉。</p><p>象曰：「王假有家」，交相愛也。</p><p>上九，有孚威如，終吉。</p><p>象曰：「威如」之吉，反身之謂也。</p><p>解讀</p><p>「家人，利女貞」者，家人謂室家之人，故孔氏雲「明家內之道，正一家之人」是也。治家之道，非丈夫獨正，內在女子，故曰「利女貞」也。</p><p>象曰「風自火出，家人」者，離火巽風。夫火之為體，因風而生，火既炎盛，還復生風，風火相成，似夫婦成家之義也。「君子以言有物而行有恆」者，「物」，事也，君子所言，皆須有事，論語典實，事不虛妄矣。所行德行，不虧於常，故曰「行有恆」也。</p><p>初九「閒有家，悔亡」者，閒，防也；夫治家之道，必須先以防慮，不令瀆亂，若候瀆亂之後方始治之，即憂悔生矣。今治家之初，便能防閒，悔必亡矣。</p><p>六二「無攸遂，在中饋，貞吉」者，以柔處中，以陰應陽，正夫婦之義也。婦人職務，但事供給饋食祭祀而已，全非遂志之人，故曰「無攸遂，在中饋，貞吉」也。</p><p>九三，家人嗃嗃，悔厲，吉。「婦子嘻嘻，終吝」者，嗃嗃，嚴整之貌；嘻嘻，喜笑之聲；悔，過也；九三處一卦之上，為一家之長，理家之道，必須嚴整，直是過於猛難，雖似危酷，後乃獲吉，故曰「家人嗃嗃，悔厲，吉」。若從婦人笑語，不制不節，終致悔吝，故曰「嘻嘻，終吝」也。</p><p>六四「富家，大吉」者，富，謂祿位昌盛之名也；六四柔巽之質，上奉於君而得其位，即是祿位昌盛而富其家，長保安吉之大也。</p><p>九五「王假有家，勿恤，吉」者，假，至也；體剛居巽而得尊位，能以巽順接待於下，至於天下盡有其家，莫不歸王之化，故不假憂恤，自然獲吉。先儒雲：猶如舜能治家，處於媯涒，即是歸讓至焉。</p><p>上九「有孚，威如，終吉」者，處家人之極，家道大成也。刑于寡妻，義彰於外，信被天下，故曰「有孚」。威及遐邇，故曰「威如」。威信並至，敬義交接，終保其吉，故曰「終吉」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
